import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`project-risk-detector`,heroTitle:`Detect project blockers before they hit`,heroSubtitle:`Perplexity Computer scans your tasks, docs, and dependencies, flags overdue work and stalled items, and delivers an early-warning report — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Connecting to your project tools, tasks, and documents`,`Scanning for overdue work, stalled tasks, and unclear ownership`,`Analyzing dependency chains and scope changes for hidden risks`,`Early-warning report with recommended actions — ready to review`],generatingSteps:[`Scanning your project tasks, docs, and timelines for risk signals`,`Designing an agent to detect overdue work, stalled tasks, and dependency conflicts`,`Configuring ownership analysis, scope-change tracking, and decision-gap detection`,`Setting up your early-warning report with prioritized recommended actions`],featureSectionTitle:`From project chaos to early warnings`,featureCardTitles:[`Connects to your project stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Trello, Notion, Google Sheets, Google Drive, Slack, Airtable — Computer pulls from your project tools so every risk signal lands in one report.`,`Overdue task alerts. Stalled workstream flags. Dependency risk maps. Missing-decision logs. A prioritized action plan to keep your project on track.`],capabilitySectionTitle:`Your risk analyst, on autopilot`,capabilitySectionSubtitle:`Connect your tools, step away, get back an early-warning report.`,capabilityCards:[{title:`Overdue Detection`,description:`Computer can scan every task and milestone across your project tools — and flag anything past due or trending late before it cascades.`},{title:`Stalled Task Alerts`,description:`Computer can identify tasks with no recent activity, unclear owners, or blocked dependencies — and surface them before they become bottlenecks.`},{title:`Scope Change Tracking`,description:`Computer can compare current tasks and docs against original plans — and flag scope creep, missing decisions, and requirement drift automatically.`},{title:`Connect Your Tools`,description:`Computer can read from Trello, Notion, Airtable, Google Drive, Slack, and Google Sheets — build workflows across your entire project management stack.`},{title:`Remember & Learn`,description:`Computer can remember your project history, past risks, and resolution patterns — so each scan gets smarter about what matters to your team.`},{title:`Monitor & Alert`,description:`Computer can re-scan your projects daily and push alerts to Slack when new risks emerge or existing ones escalate.`}]});export{t as default};
